export type StatementDrift = {
    /**
     * Outstanding balance the schedule shows on the same date, after the installments due by then, in reais, as a decimal string.
     */
    computed_balance: string;
    /**
     * Date of the outstanding balance the bank reported.
     */
    date: string;
    /**
     * The reported balance minus the computed one, in reais, as a decimal string. Positive when the bank says more is owed.
     */
    drift: string;
    /**
     * The statement's ID.
     */
    id: number;
    /**
     * Outstanding balance the bank reported, in reais, as a decimal string.
     */
    outstanding_balance: string;
};

export type StatementInput = {
    /**
     * Date of the outstanding balance the bank reported. One statement per date.
     */
    date: string;
    /**
     * Outstanding balance the bank reported, in reais, as a decimal string.
     */
    outstanding_balance: string;
};

export type StatementList = {
    /**
     * Every statement recorded on the mortgage, in date order, each with its drift from the schedule. Only this list carries the drift.
     */
    statements: Array<StatementDrift>;
};

export type Verdict = {
    /**
     * The invest scenario's net worth on the horizon less the prepay scenario's, in reais, as a decimal string. Positive favours investing. Absent when the verdict is unavailable.
     */
    advantage?: string;
    /**
     * What prepaying the amount saves by the horizon beyond the amount itself, in reais, as a decimal string. Absent when the verdict is unavailable.
     */
    avoided_cost?: string;
    /**
     * The yearly bond rate, as a decimal fraction of at most 10 places, at which buying the bond with the amount on the date gives an advantage within a centavo of zero; where the hundredths the amount buys make the advantage jump over zero, the lowest rate at which it is positive. For ntn_b_principal and ntn_b it is the real rate over IPCA, priced through the VNA of the date. Absent when the verdict is unavailable or has no_break_even.
     */
    break_even_rate?: string;
    /**
     * Investing the amount in the bond. Absent when the verdict is unavailable.
     */
    invest?: Scenario;
    /**
     * How fresh the market data the verdict reads is.
     */
    market_data: VerdictMarketData;
    /**
     * The date the bond matures: the horizon both scenarios are valued on.
     */
    maturity: string;
    /**
     * Why no yearly bond rate from 0% to 100% is a break-even rate. below_range: investing wins even at 0%; above_range: prepaying wins even at 100%. Absent when the verdict has a break_even_rate or is unavailable.
     */
    no_break_even?: 'below_range' | 'above_range';
    /**
     * Prepaying the amount. Absent when the verdict is unavailable.
     */
    prepay?: Scenario;
    /**
     * The projection method of each index a projected value of the verdict comes from. Empty when it reads published values only.
     */
    projected_by: Array<ProjectedBy>;
    /**
     * How many bonds the amount buys, in hundredths of a bond, as a decimal string. Absent when the verdict is unavailable for missing_ipca.
     */
    quantity?: string;
    /**
     * The buy rate of the bond's quote, as a decimal fraction. For ntn_b_principal and ntn_b it is the real rate over IPCA.
     */
    rate: string;
    /**
     * The type of the bond compared.
     */
    type: 'ltn' | 'ntn_f' | 'ntn_b_principal' | 'ntn_b';
    /**
     * Why the verdict has no scenarios. missing_ipca: the IPCA the bond's VNA follows is not available yet; amount_too_small: the amount buys less than a hundredth of the bond. Absent when it has them.
     */
    unavailable?: 'missing_ipca' | 'amount_too_small';
    /**
     * The price of one bond at the rate for settlement on the date, in reais, as a decimal string. Absent when the verdict is unavailable for missing_ipca.
     */
    unit_price?: string;
};

export type VerdictMarketData = {
    /**
     * How fresh the bond prices are.
     */
    bonds: BondsStatus;
    /**
     * How fresh the Focus expectations are.
     */
    focus: FocusStatus;
    /**
     * How fresh each index the verdict reads is.
     */
    indexes: Array<IndexStatus>;
};

